import { db, storage, ai, json, error, requireAuth, withScopes, type AuthUser, type RouterContext, type RouterResponse, type RouterRoutes } from '@appdeploy/sdk';
import { emitIntegrationEvent } from './integration-events';
import { writePlatformAudit } from './platform-audit';

export type FinanceAccessContext={companyId:string;projectId?:string;companyName?:string;role:string;isSuperadmin:boolean;canWrite:boolean};
type Resolver=(user:AuthUser)=>Promise<FinanceAccessContext|null>;
type Ownership='business'|'personal';
type Direction='credit'|'debit';
type Account={id:string;label:string;institution?:string;ownership:Ownership;createdAt:string};
type Tx={id:string;accountId:string;batchId:string;date:string;description:string;normalized:string;amountCents:number;direction:Direction;category:string;source:string;hash:string;createdAt:string};
type Rule={id:string;pattern:string;category:string;createdAt:string};
type ImportRec={id:string;fileName:string;fileHash:string;accountId:string;format:string;count:number;storagePath:string;createdAt:string};
export type ObligationInput={sourceId?:string;sourceType?:string;employeeId?:string;beneficiaryName?:string;document?:string;description?:string;amountCents?:number;amount?:number;dueDate?:string;competence?:string;category?:string;projectId?:string;status?:string};
