function protectedRoute(resolve:Resolver,write:boolean,fn:(c:RouterContext,f:FinanceAccessContext)=>Promise<RouterResponse>|RouterResponse){return[requireAuth(),withScopes('email','profile'),async(c:RouterContext)=>{const f=await resolve(c.user!);if(!f)return error('Financeiro não liberado para esta credencial.',403);if(write&&!f.canWrite)return error('Seu perfil financeiro é somente consulta.',403);return fn(c,f)}]}
export async function desktopFinanceRead(companyId:string,view:string){if(view==='accounts')return{accounts:await accounts(companyId)};if(view==='dashboard'){const[a,t,o,m]=await Promise.all([accounts(companyId),transactions(companyId),obligations(companyId),matches(companyId)]),bank=bankDashboard(t,a),os=obligationStats(o,m),sg=suggestions(t,a,o,m);return{...bank,expected:os,suggestionsCount:sg.length}}if(view==='transactions'){const[a,t,m]=await Promise.all([accounts(companyId),transactions(companyId),matches(companyId)]),r=accountReconcile(t,a),map=new Map(a.map(x=>[x.id,x])),tot=allocationTotals(m);return{transactions:t.sort((x,y)=>y.date.localeCompare(x.date)).map(x=>({...x,accountLabel:map.get(x.accountId)?.label||'Conta',internalTransfer:r.internal.has(x.id),relatedWithdrawal:r.withdrawals.has(x.id),matchedCents:tot.byTx.get(x.id)||0}))}}if(view==='obligations'){const[o,m]=await Promise.all([obligations(companyId),matches(companyId)]);return obligationStats(o,m)}if(view==='reconciliation'){const[a,t,o,m]=await Promise.all([accounts(companyId),transactions(companyId),obligations(companyId),matches(companyId)]);return{suggestions:suggestions(t,a,o,m),confirmed:m}}if(view==='gemini-status'){const cfg=await geminiConfig(companyId);return{configured:!!cfg?.apiKey,model:cfg?.model||GEMINI_MODEL}}if(view==='categories')return{categories:CATEGORIES};if(view==='imports')return{imports:await imports(companyId)};throw new Error('Consulta financeira Desktop inválida.')}
