export async function migrateLegacyFinancePayload(companyId:string,actorUserId:string,payload:unknown){
  const b=obj(payload),source='artisys-finance-v1',sourceUserId=txt(b.sourceUserId)||'unknown';
  const legacyAccounts=list<Record<string,unknown>>(b.accounts).slice(0,100),legacyTx=list<Record<string,unknown>>(b.transactions).slice(0,500),legacyRules=list<Record<string,unknown>>(b.rules).slice(0,200),legacyImports=list<Record<string,unknown>>(b.imports).slice(0,150);
  const canonicalAccounts=await all<Record<string,unknown>>(companyId,'accounts',200),accountMap=new Map<string,string>();let accountsAdded=0;
  for(const raw of legacyAccounts){const oldId=txt(raw.id);if(!oldId)continue;const legacyKey=source+'|'+sourceUserId+'|'+oldId;let current=canonicalAccounts.find(x=>String(x.legacyKey||'')===legacyKey);if(!current){const label=txt(raw.label)||'Conta migrada',ownership=txt(raw.ownership)==='personal'?'personal':'business',[id]=await db.add(table(companyId,'accounts'),[{label,institution:txt(raw.institution),ownership,legacyKey,migratedAt:now(),createdAt:txt(raw.createdAt)||now()}]);if(id){current={id,label,ownership,legacyKey};canonicalAccounts.push(current);accountsAdded++}}if(current?.id)accountMap.set(oldId,String(current.id))}
  const existingTx=await transactions(companyId),hashes=new Set(existingTx.map(x=>x.hash)),fresh:Array<Omit<Tx,'id'>>=[];
  for(const raw of legacyTx){const oldAccountId=txt(raw.accountId),accountId=accountMap.get(oldAccountId);if(!accountId)continue;const description=txt(raw.description)||'Lançamento migrado',normalized=txt(raw.normalized)||normalize(description),amountCents=Math.max(0,Math.round(Number(raw.amountCents||0))),direction=txt(raw.direction)==='credit'?'credit':'debit',date=txt(raw.date)||now().slice(0,10),hash=txt(raw.hash)||stableHash(accountId+'|'+date+'|'+normalized+'|'+amountCents+'|'+direction);if(!amountCents||hashes.has(hash))continue;hashes.add(hash);fresh.push({accountId,batchId:txt(raw.batchId)||('legacy-'+stableHash(sourceUserId).slice(0,12)),date,description,normalized,amountCents,direction,category:CATEGORIES.includes(txt(raw.category))?txt(raw.category):'A conciliar',source:'legacy-migration',hash,createdAt:txt(raw.createdAt)||now()})}
  const txIds=fresh.length?await db.add(table(companyId,'tx'),fresh):[],existingRules=await rules(companyId);let rulesAdded=0;
  for(const raw of legacyRules){const pattern=txt(raw.pattern),category=txt(raw.category);if(!pattern||!CATEGORIES.includes(category)||existingRules.some(x=>x.pattern===pattern))continue;const[id]=await db.add(table(companyId,'rules'),[{pattern,category,createdAt:txt(raw.createdAt)||now(),legacySource:source}]);if(id){rulesAdded++;existingRules.push({id,pattern,category,createdAt:now()})}}
  const existingImports=await imports(companyId);let importsAdded=0;
  for(const raw of legacyImports){const fileHash=txt(raw.fileHash);if(!fileHash||existingImports.some(x=>x.fileHash===fileHash))continue;const[id]=await db.add(table(companyId,'imports'),[{fileName:txt(raw.fileName)||'arquivo-legado',fileHash,accountId:accountMap.get(txt(raw.accountId))||'',format:txt(raw.format)||'legacy',count:Number(raw.count||0),storagePath:'legacy://'+txt(raw.storagePath),legacySource:source,createdAt:txt(raw.createdAt)||now()}]);if(id)importsAdded++}
  const report={source,sourceUserId,accountsReceived:legacyAccounts.length,accountsAdded,transactionsReceived:legacyTx.length,transactionsAdded:txIds.filter(Boolean).length,rulesAdded,importsAdded,legacyFilesPreserved:true};
  await emitIntegrationEvent({type:'finance.legacy.migrated',companyId,source:'finance',actorUserId,payload:report});
  await writePlatformAudit({action:'FINANCE_LEGACY_MIGRATED',actorUserId,companyId,entity:'finance',source:'finance',metadata:report});
  return report
}

